import java.io.*;
import java.util.*;

public class E {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long kt = Long.parseLong(st.nextToken());

        if (kt >= n) {
            System.out.println(0);
            return;
        }

        int k = (int) kt;
        long mod = 998244353L;
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % mod;
        }

        long answer = 0;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long comb = (fact[c] * modInverse(fact[i], mod) % mod) * modInverse(fact[c - i], mod) % mod;
            long power = modPow(c - i, n, mod);
            long t = (comb * power) % mod;
            if (i % 2 == 0) {
                answer = (answer + t) % mod;
            } else {
                answer = (answer - t + mod) % mod;
            }
        }
        long totalComb = (fact[n] * modInverse(fact[n - k], mod) % mod) * modInverse(fact[k], mod) % mod;
        answer = (answer * totalComb) % mod;
        if (k > 0) answer = (answer * 2) % mod;
        System.out.println(answer);
    }

    private static long modInverse(long a, long m) {
        return modPow(a, m - 2, m);
    }

    private static long modPow(long base, int exp, long m) {
        long result = 1;
        long b = base % m;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % m;
            }
            b = (b * b) % m;
            e >>= 1;
        }
        return result;
    }
}
